//
//  OpenSSHKeyTests.swift
//  sshconfigmanagerTests
//
//  Validates the OpenSSH private-key parser against a real (throwaway) key:
//  the parsed seed must derive, via CryptoKit, the same public key the parser
//  read from the file — proving the parse is correct end to end.
//

import CryptoKit
import Foundation
import SSHConfigCore
import SSHConfigCrypto
import SSHConfigServices
import Testing

@testable import SSHConfigMacUI

struct OpenSSHKeyTests {
