        -----END OPENSSH PRIVATE KEY-----
        """

    @Test func parsesUnencryptedEd25519() throws {
        let parsed = try OpenSSHPrivateKey.parse(pem: unencryptedEd25519)
        #expect(parsed.keyType == "ssh-ed25519")
        #expect(parsed.ed25519Seed?.count == 32)
        #expect(parsed.publicKey.count == 32)
    }

    @Test func parsedSeedDerivesTheStoredPublicKey() throws {
        let parsed = try OpenSSHPrivateKey.parse(pem: unencryptedEd25519)
        // The whole point: seed → CryptoKit private key → public key must match
        // the public key bytes the parser independently read from the file.
        let seed = try #require(parsed.ed25519Seed)
        let key = try Curve25519.Signing.PrivateKey(rawRepresentation: seed)
        #expect([UInt8](key.publicKey.rawRepresentation) == parsed.publicKey)
    }

    @Test func parsesEcdsaP256AndScalarDerivesPoint() throws {
        let parsed = try OpenSSHPrivateKey.parse(pem: unencryptedEcdsaP256)
        #expect(parsed.keyType == "ecdsa-sha2-nistp256")
        guard case .ecdsa(let curve, let scalar) = parsed.material else {
            Issue.record("expected ecdsa material")
            return
        }
        #expect(curve == .p256)
        #expect(scalar.count == 32)
        // The scalar must reconstruct the public EC point (x963 = 0x04‖X‖Y) the
        // parser read independently from the file.
        let key = try P256.Signing.PrivateKey(rawRepresentation: Data(scalar))
        #expect([UInt8](key.publicKey.x963Representation) == parsed.publicKey)
    }

    private func sshStr(_ s: String) -> [UInt8] { SSHAgentProtocol.string(Array(s.utf8)) }

    @Test func rejectsUnsupportedKDF() {
        // cipher is supported (aes256-ctr) but the KDF isn't bcrypt → unsupportedKDF.
        var blob = Array("openssh-key-v1\0".utf8)
        blob += sshStr("aes256-ctr") + sshStr("scrypt") + sshStr("") + [0, 0, 0, 1]
        blob += sshStr("pub") + sshStr("priv")
        let pem =
            "-----BEGIN OPENSSH PRIVATE KEY-----\n\(Data(blob).base64EncodedString())\n-----END OPENSSH PRIVATE KEY-----"
        #expect(throws: OpenSSHKeyError.unsupportedKDF("scrypt")) {
            try OpenSSHPrivateKey.parse(pem: pem)
        }
    }

    @Test func rejectsNonOpenSSHText() {
        #expect(throws: OpenSSHKeyError.self) {
            try OpenSSHPrivateKey.parse(pem: "not a key")
        }
    }

    /// A throwaway ed25519 key encrypted (aes256-ctr / bcrypt) with passphrase "hunter2".
    private let encryptedEd25519 = """
        -----BEGIN OPENSSH PRIVATE KEY-----
        b3BlbnNzaC1rZXktdjEAAAAACmFlczI1Ni1jdHIAAAAGYmNyeXB0AAAAGAAAABACZOWjdA
        MCFAIVMfEmvJL+AAAAGAAAAAEAAAAzAAAAC3NzaC1lZDI1NTE5AAAAIHmj12rCUiiVT2J/
        5lCNLndG1KC/u6wK525jLcdGnqWBAAAAoOr/xDQA74UZn6wg/1QtnWMFOiqbuNUULPVBP3
        e5qi/kpnkEsypeMgAydJQmk72YlwSFhXHGKlOZUW7/tdCvgXr3VeitwK1KLv+p7TabmhDA
        thLTFaHYI166a3dyBTmLs3c0FOpDVsDXom4NquEd0JoRSt9QwFjJzpLM3k9UB38gotANoY
        XnqbJttOYanWMkL0C2bbtYYl4yw1oFCXgX6oU=
        -----END OPENSSH PRIVATE KEY-----
        """
    /// The public key bytes for the encrypted key above (base64 of the 32-byte ed25519 point).
    private let encryptedPublicKeyB64 = "eaPXasJSKJVPYn/mUI0ud0bUoL+7rArnbmMtx0aepYE="

    @Test func decryptsPassphraseProtectedEd25519() throws {
        // The whole bcrypt_pbkdf + AES-CTR chain: with the right passphrase, the
        // recovered seed must derive the key's real public key.
        let parsed = try OpenSSHPrivateKey.parse(pem: encryptedEd25519, passphrase: "hunter2")
        #expect(parsed.keyType == "ssh-ed25519")
        let seed = try #require(parsed.ed25519Seed)
        let key = try Curve25519.Signing.PrivateKey(rawRepresentation: seed)
        #expect([UInt8](key.publicKey.rawRepresentation) == parsed.publicKey)
        #expect(Data(parsed.publicKey).base64EncodedString() == encryptedPublicKeyB64)
    }

    @Test func wrongPassphraseIsRejected() {
        #expect(throws: OpenSSHKeyError.incorrectPassphrase) {
            try OpenSSHPrivateKey.parse(pem: encryptedEd25519, passphrase: "wrong")
        }
    }

    @Test func encryptedKeyWithoutPassphraseAsksForOne() {
        #expect(throws: OpenSSHKeyError.passphraseRequired) {
            try OpenSSHPrivateKey.parse(pem: encryptedEd25519)
        }
    }

