    /// The base64 body (after "ssh-rsa ") of the encrypted RSA key's .pub file.
    private let encryptedRSAPubB64 =
        ""

    /// Recomputes the `ssh-rsa` public-key blob (`string "ssh-rsa"`, `mpint e`,
    /// `mpint n`) from the parsed components, so it can be checked against the .pub
    /// blob ssh-keygen wrote — the crux of a correct RSA parse. (Pure local encoding;
    /// the full NIOSSHRSA crypto round trip lives in the package's NIOSSHRSATests.)
    private func sshRSAPublicBlobB64(n: [UInt8], e: [UInt8]) -> String {
        func mpint(_ magnitude: [UInt8]) -> [UInt8] {
            var m = Array(magnitude.drop { $0 == 0 })
            if let first = m.first, first & 0x80 != 0 { m.insert(0, at: 0) }
            let len = UInt32(m.count)
            return [
                UInt8(len >> 24 & 0xff), UInt8(len >> 16 & 0xff),
                UInt8(len >> 8 & 0xff), UInt8(len & 0xff),
            ] + m
        }
        var blob = sshStr("ssh-rsa")
        blob += mpint(e)
        blob += mpint(n)
        return Data(blob).base64EncodedString()
    }

    @Test func parsesUnencryptedRSA() throws {
        let parsed = try OpenSSHPrivateKey.parse(pem: unencryptedRSA)
        #expect(parsed.keyType == "ssh-rsa")
        guard case .rsa(_, let e, _, _, _) = parsed.material else {
            Issue.record("expected rsa material")
            return
        }
        #expect(e == [0x01, 0x00, 0x01]) // standard RSA public exponent 65537
    }

    /// The whole point: the parsed RSA components must reconstruct the exact
    /// `ssh-rsa` public-key blob ssh-keygen wrote to the .pub file.
    @Test func parsedRSAComponentsRebuildTheStoredPublicKey() throws {
        let parsed = try OpenSSHPrivateKey.parse(pem: unencryptedRSA)
        guard case .rsa(let n, let e, _, _, _) = parsed.material else {
            Issue.record("expected rsa material")
            return
        }
        #expect(sshRSAPublicBlobB64(n: n, e: e) == unencryptedRSAPubB64)
    }

    /// bcrypt_pbkdf + AES-CTR over an RSA key: decrypting with the right passphrase
    /// must rebuild the encrypted key's real public blob.
    @Test func decryptsPassphraseProtectedRSA() throws {
        let parsed = try OpenSSHPrivateKey.parse(pem: encryptedRSA, passphrase: "hunter2")
        #expect(parsed.keyType == "ssh-rsa")
        guard case .rsa(let n, let e, _, _, _) = parsed.material else {
            Issue.record("expected rsa material")
            return
        }
        #expect(sshRSAPublicBlobB64(n: n, e: e) == encryptedRSAPubB64)
    }

    // MARK: - Cleartext public-key info (no passphrase needed)

    /// ssh-keygen fingerprints of the embedded test keys (`ssh-keygen -lf …`).
    private let unencryptedRSAFingerprint = "SHA256:RI4GbBb1zha+dgzo5E6wTgHVT5xoW4qF1KLNB8heuwA"
    private let encryptedRSAFingerprint = "SHA256:lWJl7ExjRWqIV8878XGjfEcjreg94f6zv8UBRW9r/H4"

    @Test func publicKeyInfoMatchesSSHKeygenForRSA() throws {
        let info = try #require(OpenSSHPrivateKey.publicKeyInfo(pem: unencryptedRSA))
        #expect(info.keyType == "ssh-rsa")
        #expect(SSHKeyService.fingerprint(blob: info.blob) == unencryptedRSAFingerprint)
    }

    /// The crux of the fix: the public blob (and thus type + fingerprint) is readable
    /// from an *encrypted* key **without** the passphrase.
    @Test func publicKeyInfoReadsEncryptedRSAWithoutPassphrase() throws {
        let info = try #require(OpenSSHPrivateKey.publicKeyInfo(pem: encryptedRSA))
        #expect(info.keyType == "ssh-rsa")
        #expect(SSHKeyService.fingerprint(blob: info.blob) == encryptedRSAFingerprint)
    }

    @Test func publicKeyInfoHandlesEd25519() throws {
        let info = try #require(OpenSSHPrivateKey.publicKeyInfo(pem: unencryptedEd25519))
        #expect(info.keyType == "ssh-ed25519")
        #expect(SSHKeyService.fingerprint(blob: info.blob)?.hasPrefix("SHA256:") == true)
    }

    @Test func publicKeyInfoRejectsNonOpenSSH() {
        #expect(OpenSSHPrivateKey.publicKeyInfo(pem: "not a key") == nil)
    }

    @Test func isEncryptedDetectsCipher() {
        #expect(OpenSSHPrivateKey.isEncrypted(pem: encryptedRSA) == true)
        #expect(OpenSSHPrivateKey.isEncrypted(pem: encryptedEd25519) == true)
        #expect(OpenSSHPrivateKey.isEncrypted(pem: unencryptedRSA) == false)
        #expect(OpenSSHPrivateKey.isEncrypted(pem: unencryptedEd25519) == false)
        // Unparseable input is `nil` (unknown), NOT a definitive `false` — so it isn't
        // audited as "has no passphrase" (audit #33).
        #expect(OpenSSHPrivateKey.isEncrypted(pem: "not a key") == nil)
        #expect(
            OpenSSHPrivateKey.isEncrypted(
                pem:
                    "-----BEGIN OPENSSH PRIVATE KEY-----\n@@@not base64@@@\n-----END OPENSSH PRIVATE KEY-----") == nil)
    }

    @Test func classicPEMAlgorithmDetectsType() {
        #expect(SSHKeyService.classicPEMAlgorithm("-----BEGIN RSA PRIVATE KEY-----\n…") == "ssh-rsa")
        #expect(SSHKeyService.classicPEMAlgorithm("-----BEGIN EC PRIVATE KEY-----\n…") == "ecdsa")
        #expect(SSHKeyService.classicPEMAlgorithm("-----BEGIN DSA PRIVATE KEY-----\n…") == "ssh-dss")
        #expect(SSHKeyService.classicPEMAlgorithm("-----BEGIN PRIVATE KEY-----\n…") == "") // PKCS#8
    }

    // MARK: - Key discovery (the bug: standalone private keys must be listed)

    private let classicRSAPEM = """
        -----BEGIN RSA PRIVATE KEY-----
        MIIBOgIBAAJBAKj34GkxFhD90vcNLYLInFEX6Ppy1tPf9Cnzj4p4WGeKLs1Pt8Qu
        KUpRKfFLfRYC9AIKjbJTWit+CqvjWYzvQwECAwEAAQ==
        -----END RSA PRIVATE KEY-----
        """

    @Test func discoverKeysListsStandalonePrivateKeysAndPairsPublics() throws {
        let dir = URL(fileURLWithPath: "/Users/test/.ssh")
        func u(_ name: String) -> URL { dir.appendingPathComponent(name) }
        let files = [
            u("id_rsa"), u("id_rsa.pub"), // paired public + private
            u("legacy-enc"),
            u("prod.pem"), // standalone classic-PEM private, no .pub
            u("config"), u("known_hosts"), // must be ignored
        ]
        let contents: [String: String] = [
            "id_rsa": unencryptedRSA,
            "id_rsa.pub": "ssh-rsa \(unencryptedRSAPubB64) rsa-test@local",
            "legacy-enc": encryptedRSA,
            "prod.pem": classicRSAPEM,
            "config": "Host foo\n  HostName example.com\n",
            "known_hosts": "example.com ssh-ed25519 AAAAC3...\n",
        ]
        let keys = SSHKeyService.discoverKeys(files: files) { contents[$0.lastPathComponent] }
        let names = keys.map(\.name)

        // The bug fix: standalone private keys (no .pub) are now listed…
        #expect(names.contains("legacy-enc"))
        #expect(names.contains("prod.pem"))
        // …while non-key files are not.
        #expect(!names.contains("config"))
        #expect(!names.contains("known_hosts"))

        let paired = try #require(keys.first { $0.name == "id_rsa" })
        #expect(paired.publicKeyURL != nil)
        #expect(paired.privateKeyURL != nil)
        #expect(paired.fingerprint == unencryptedRSAFingerprint)

        // Standalone encrypted key: typed + fingerprinted without a passphrase.
        let standalone = try #require(keys.first { $0.name == "legacy-enc" })
        #expect(standalone.publicKeyURL == nil)
        #expect(standalone.privateKeyURL == u("legacy-enc"))
        #expect(standalone.algorithm == "ssh-rsa")
        #expect(standalone.fingerprint == encryptedRSAFingerprint)
        #expect(standalone.identityFilePath == "/Users/test/.ssh/legacy-enc")

        // Classic PEM: best-effort type, no fingerprint.
        let pem = try #require(keys.first { $0.name == "prod.pem" })
        #expect(pem.algorithm == "ssh-rsa")
        #expect(pem.typeLabel == "RSA")
        #expect(pem.fingerprint.isEmpty)
    }

    @Test func discoverKeysDoesNotDoubleListPairedPrivateKeys() {
        let dir = URL(fileURLWithPath: "/Users/test/.ssh")
        let files = [dir.appendingPathComponent("id_rsa"), dir.appendingPathComponent("id_rsa.pub")]
        let contents = [
            "id_rsa": unencryptedRSA,
            "id_rsa.pub": "ssh-rsa \(unencryptedRSAPubB64) rsa-test@local",
        ]
        let keys = SSHKeyService.discoverKeys(files: files) { contents[$0.lastPathComponent] }
        #expect(keys.count == 1) // one entry, not the .pub + a phantom private
        #expect(keys[0].privateKeyURL != nil)
    }
}
